  {:ok, %{direction: :start, ref: ref, type: type, params: params}}
end
def parse(["-" <> ref]) when ref != "" do
  {:ok, %{direction: :end, ref: ref}}
end
def parse(["+" | _params]) do
  {:error, :missing_reference}
end
def parse(["-" | _params]) do
  {:error, :missing_reference}
end
def parse(_params) do
  {:error, :invalid_reference}
end

