           {{:"$1", :"$2", :"$3", :"$4"},
            [{:andalso, {:==, :"$1", key}, {:"=<", {:+, :"$3", 1}, :"$2"}}],
            [{{:"$1", :"$2", {:+, :"$3", 1}, :"$4"}}]}
