def find_next_word(code) do
  walk_text(code, nil, fn
    grapheme, rest, _, _, _ when grapheme in @empty_graphemes -> {rest, nil}
    _grapheme, rest, line, col, _ -> {"", {rest, line - 1, col - 1}}
  end)
end

def split_module_and_func(call, current_module \\ nil, aliases \\ [])
def split_module_and_func("", _current_module, _aliases) do
  {nil, nil}
end
def split_module_and_func(call, current_module, aliases) do
  case Code.string_to_quoted(call, emit_warnings: false) do
    {:error, _} -> {nil, nil}
    {:ok, quoted} when is_atom(quoted) -> {quoted, nil}
    {:ok, quoted} -> split_mod_quoted_fun_call(quoted, current_module, aliases)
  end
end

