def patches_to_edits(%Document{} = document, patches) do
  maybe_edits =
    Enum.reduce_while(patches, [], fn patch, edits ->
      case patch_to_edit(document, patch) do
        {:ok, edit} -> {:cont, [edit | edits]}
        error -> {:halt, error}
      end
    end)

  case maybe_edits do
    edits when is_list(edits) -> {:ok, Enum.reverse(edits)}
    error -> error
  end
end

