    [id] ->
      {:ok, %__MODULE__{id: id}}

    [id, app_data] ->
      msid = %__MODULE__{id: id, app_data: app_data}
      {:ok, msid}

    _invalid_msid ->
      {:error, :invalid_msid}
  end
end

