  |> String.split(",")
  |> Enum.reduce_while({:ok, []}, fn parameter_set, {:ok, acc} ->
    case Base.decode64(parameter_set) do
      {:ok, decoded} -> {:cont, {:ok, acc ++ [decoded]}}
      :error -> {:halt, {:error, :invalid_ps}}
    end
  end)
