def split(origin, delim, expected_len) do
  split = String.split(origin, delim)

  cond do
    length(split) == expected_len -> {:ok, split}
    length(split) < expected_len -> {:error, :too_few_fields}
    length(split) > expected_len -> {:error, :too_many_fields}
  end
end

