def used_assigns(expr) do
  {_expr, assigns} =
    Macro.prewalk(expr, [], fn
      {:@, _meta, [{assign, meta, _}]} = expr, assigns -> {expr, [{assign, meta} | assigns]}
      expr, assigns -> {expr, assigns}
    end)

  assigns
end

